#include <bits/stdc++.h>
using namespace std;

const int N=16,V=5*N;
enum {S,A,B,C,D};
int n,d,x[N],R[N],par[V],lo[V],hi[V],tin[V],tout[V],tim;
int cutL[N][2],cutR[N][2],good[N][N],invr[N][N];
int lc,rc,last;
long long cases,queries;
vector<int> g[V];

int id(int p,int s) { return (p-1)*5+s; }
int ways(int s,int v) {
    if(s==S) return 1;
    if(s==D) return 3;
    if(s==C) return v>rc?2:3;
    if(v>rc) return 1;
    return s==A&&v>lc?2:3;
}
void dfs(int u) {
    tin[u]=++tim;
    for(int v:g[u]) dfs(v);
    tout[u]=tim;
}
bool check() {
    for(int i=1;i<=n;i++) {
        R[i]=i;
        while(R[i]<n&&x[R[i]+1]-x[i]<=d) ++R[i];
    }
    for(int z=0;z<5*n;z++) g[z].clear();
    for(int i=1;i<=n;i++) for(int s=S;s<=D;s++) {
        int z=id(i,s),h=R[i];
        lc=max(i,i>2?R[i-2]:0);
        rc=max(i,i>1?R[i-1]:0);
        lo[z]=hi[z]=i;
        par[z]=-1;
        if(h==i) continue;
        if(s==A) lo[z]=lc,hi[z]=rc;
        if(s==C) lo[z]=rc,hi[z]=h;
        int f=ways(s,h),t;
        if(f==3) t=D;
        else if(f==2) t=C;
        else t=h==i+1||ways(s,h-1)==1?A:B;
        par[z]=id(h,t);
        g[par[z]].push_back(z);
    }
    tim=0;
    for(int z=0;z<5*n;z++) if(par[z]<0) dfs(z);
    int first=1;
    for(int v=1;v<=n;v++) {
        while(R[first]<v) ++first;
        for(int j=0;j<2;j++) {
            cutL[v][j]=1; cutR[v][j]=0;
            if(first+j>n) continue;
            int z=id(first+j,j==0?C:A);
            if(lo[z]<v&&v<=hi[z]) cutL[v][j]=tin[z],cutR[v][j]=tout[z];
        }
    }
    for(int u=1;u<=n;u++) {
        int ds[N],f[N]={},p=tin[id(u,S)];
        fill(ds,ds+n+1,-1);
        queue<int> q; q.push(u); ds[u]=0; f[u]=1;
        while(!q.empty()) {
            int a=q.front();q.pop();
            for(int v=1;v<=n;v++) if(v!=a&&abs(x[a]-x[v])<=d) {
                if(ds[v]<0) ds[v]=ds[a]+1,q.push(v);
                if(ds[v]==ds[a]+1) f[v]=min(3,f[v]+f[a]);
            }
        }
        for(int v=1;v<=n;v++) {
            good[u][v]=u<v&&f[v]==2;
            invr[u][v]=0;
            for(int j=0;j<2;j++) invr[u][v]+=(p>cutL[v][j]-1)-(p>cutR[v][j]);
            if(good[u][v]!=invr[u][v]) return false;
        }
    }
    for(int l=1;l<=n;l++) for(int r=l;r<=n;r++) {
        int sum=0,ans=0;
        for(int u=l;u<=r;u++) for(int v=l;v<=r;v++) sum+=good[u][v],ans+=invr[u][v];
        ++queries;
        if(sum!=ans) return false;
    }
    ++cases;
    return true;
}
int main() {
    for(int m=0;m<(1<<10);m++) {
        n=1; x[1]=0;
        for(int j=1;j<=10;j++) if(m>>(j-1)&1) x[++n]=j;
        for(d=1;d<=11;d++) if(!check()) { cout<<"mismatch "<<m<<" "<<d<<endl;return 1; }
    }
    cout<<"instances="<<cases<<" interval queries="<<queries<<endl;
}
